"""Join exhaustive option counts with source provenance and benchmark-relevance notes."""
import collections,csv,html,json,pathlib,re
import yaml
P=pathlib.Path(__file__).resolve().parents[1]/'outputs/tasksource-source-audit'
D={
'ai2_arc/ARC-Challenge/challenge':'Science examination MCQs from ARC Challenge; a small subset has at least five supplied options.', 'ai2_arc/ARC-Easy/challenge':'Science examination MCQs from ARC Easy; a small subset has at least five supplied options.', 'AES2-essay-scoring':'Holistic scoring of student essays.', 'IntentGrasp/all':'Classify user utterances into an intent taxonomy.', 'SpaRTUN':'Reason about spatial relations in generated descriptions.', 'TuringBench':'Identify the human or generator model that produced text.', 'app_reviews':'Predict an app review star rating.', 'banking77':'Classify banking customer requests into 77 intents.', 'biored/relation':'Classify biomedical relations between marked entities.', 'blog_authorship_corpus/job':'Infer a blogger’s occupational industry.', 'chemprot/chemprot_full_source':'Identify chemical–protein relation types.', 'cicero':'Select a commonsense inference about a dialogue: causes, motives or consequences.', 'circa':'Interpret an indirect answer to a yes/no question.', 'citation_intent':'Classify the purpose of a scientific citation.', 'clinc_oos/plus':'Classify assistant intents, including out-of-scope requests.', 'clutrr':'Infer family/kinship relations from relational stories.', 'commonsense_qa':'Select an answer to a commonsense question.', 'conll2003/ner_tags':'Classify the named-entity label of a target token.', 'crowdflower/political-media-message':'Classify the type of political message.', 'cycic_multiplechoice':'Select a commonsense answer from supplied alternatives.', 'dbpedia_14/dbpedia_14':'Classify text into DBpedia entity/topic categories.', 'ddi/relation':'Classify drug–drug interaction types.', 'dgen':'Select an answer in an existing multiple-choice question.', 'discogem/relation':'Predict annotated discourse relations between text spans.', 'discovery/discovery':'Choose the discourse connective linking two text spans.', 'dnd_style_intents':'Classify conversational intents in a role-playing setting.', 'docred':'Identify document-level relations between entity pairs.', 'empathetic-dialogues/emotion':'Identify the speaker’s reported emotion.', 'go_emotions/simplified':'Classify emotions in text; includes derived grouped decisions.', 'head_qa/en':'Answer English-language healthcare examination questions.', 'it-support-tickets':'Route or classify IT support tickets.', 'joci':'Judge how likely a hypothesis is given a context.', 'language-identification':'Identify the language of text.', 'lex_glue/case_hold':'Choose the legal holding completing a judicial passage.', 'lex_glue/ledgar':'Classify contractual provisions into clause categories.', 'lex_glue/scotus':'Classify US Supreme Court opinions by issue area.', 'lex_glue/unfair_tos':'Classify types of potentially unfair terms-of-service clauses.', 'liar':'Classify the graded truthfulness of political claims.', 'linguisticprobing/top_constituents':'Identify the top-level syntactic constituent sequence.', 'logical-fallacy':'Classify the logical fallacy in an argument.', 'lsat-ar':'Answer LSAT analytical reasoning questions.', 'lsat-rc':'Answer LSAT reading comprehension questions.', 'lsat_qa/all':'Answer LSAT questions across included sections.', 'math_qa':'Answer existing mathematical word-problem MCQs.', 'maven-arg/role':'Identify an argument’s semantic role in an event.', 'maven/event':'Classify the event type of a marked trigger.', 'multiwoz22/categorical-slot':'Select the categorical slot value from a dialogue state.', 'multiwoz22/dialogue-act':'Classify the dialogue act of a user utterance.', 'numer_sense':'Choose the missing numerical quantity in a commonsense statement.', 'open_question_type':'Classify the type of information requested by a question.', 'patent-classification/abstract':'Classify inventions by patent section.', 'patent-phrase-similarity':'Judge similarity between phrases in a patent context.', 'persuasion':'Classify persuasion-related outcomes or strategies.', 'privacy-200k-Mistral-Large-3':'Rate text privacy/sensitivity on a five-level scale.', 'proto_qa/proto_qa':'Select common answers to everyday survey-style questions; vote-derived targets.', 'pubmed-rct/role':'Classify rhetorical roles of sentences in clinical-trial abstracts.', 'qasc':'Eight-way science QA requiring composition of facts.', 'riddle_sense':'Select an answer to a commonsense riddle.', 'sciie':'Classify scientific information-extraction relation labels.', 'scruples/verdict_votes':'Predict graded/distributed moral verdicts about social situations.', 'sem_eval_2010_task_8':'Classify semantic relations between marked nominals.', 'semcor':'Choose the WordNet sense of a marked expression in context.', 'slurp/intent':'Classify spoken-assistant intents.', 'slurp/slot-type':'Classify semantic slots in spoken-assistant requests.', 'snips_built_in_intents':'Classify assistant utterances into built-in intents.', 'spider/column':'Choose the database column needed by a natural-language query.', 'stepgame':'Infer spatial relations from chains of statements.', 'topv2/intent':'Classify the top-level task-oriented intent.', 'topv2/slot-type':'Classify a marked expression’s semantic slot.', 'trec':'Classify questions by expected answer type.', 'tweet_eval/emoji':'Predict the emoji category associated with a tweet.', 'twentyquestions':'Classify answers to object-property questions in a twenty-questions setting.', 'webinstruct/mc':'Multiple-choice questions from a broad web-instruction collection.', 'weblinx/action':'Select the next browser operation from interaction context.', 'weblinx/dom-element':'Choose the DOM element targeted by a browser operation.', 'websrc/element':'Locate the DOM element containing a question’s answer.', 'wiki_hop/original':'Select an entity answer using multiple supporting documents.', 'wikimedqa/medwiki':'Eight-choice medical question answering.', 'wikisql/aggregation':'Choose the SQL aggregation for a natural-language query.', 'wikisql/column':'Choose the table column for a natural-language query.', 'wnut_17/wnut_17':'Classify emerging named entities in social-media text.', 'yahoo_answers_topics':'Classify questions/documents into Yahoo topic categories.', 'yelp_review_full/yelp_review_full':'Predict five-level Yelp review ratings.'}
PROC={'arithmetic':'Execute arithmetic or account-balance calculations.','entity_belief_tracking':'Track entities’ actual locations and agents’ beliefs.','event_triggered_execution':'Apply timestamped rules to incoming events.','evidence_sufficiency':'Assess valid support and compare evidence reliability.','goal_directed_planning':'Choose an executable action toward a stated goal.','graph_navigation':'Choose route properties or costs in a graph.','instruction_execution':'Execute requests under explicit instructions and policies.','needle_retrieval':'Retrieve specified facts from distractor-filled records.','policy_applicability':'Select the highest-priority applicable policy.','policy_under_uncertainty':'Evaluate policies when some facts are uncertain.','record_aggregation':'Aggregate/filter records and select a result.','record_eligibility':'Select eligible records under explicit constraints.','state_perturbation':'Identify meaningful changes between structured states.','table_lookup':'Retrieve or compare information in structured tables.','taxonomy_routing':'Route requests using a supplied taxonomy.'}
def describe(s,questions):
 if s in D:return D[s]
 if s.startswith('procedural-typed-decisions/'):return 'Procedurally generated task: '+PROC.get(s.split('/')[-1],s.split('/')[-1].replace('_',' '))
 if s.startswith(('HelpSteer/','HelpSteer2/')):return 'Rate assistant-response '+s.split('/')[-1]+' using verbal/numeric levels, encoded here as Choice.'
 if s=='HelpSteer3/feedback':return 'Rate assistant helpfulness using five verbal levels.'
 if s=='HelpSteer3/preference_strength':return 'Seven-level comparison from Response 1 much better to Response 2 much better.'
 if s.startswith('english-grading/'):return 'Score English-learner essay '+s.split('/')[-1]+' on a graded rubric.'
 if 'disrpt/' in s:return 'Classify discourse relations in '+s.split('disrpt/')[-1]+' (language/treebank-specific view).'
 if s.startswith('multidogo/'):return 'Classify dialogue intents in the '+s.split('/')[1]+' domain.'
 if s.startswith('multilingual/xcsr/X-CSQA-'):return 'Translated CommonsenseQA multiple-choice questions; language '+s.rsplit('-',1)[-1]+'.'
 if s.startswith('multilingual/masakhanews/'):return 'News-topic classification; language '+s.rsplit('/',1)[-1]+'.'
 if s.startswith('multilingual/offenseval_dravidian/'):return 'Classify offensive-language categories in '+s.rsplit('/',1)[-1]+'.'
 if s.startswith('multilingual/'):
  low=s.lower()
  if any(t in low for t in ['language-identification','wili_2018']):return 'Multilingual language identification.'
  if 'amazon_reviews' in low:return 'Multilingual five-star review rating.'
  if 'massive' in low:return 'Multilingual assistant-intent classification.'
  if 'mtop' in low:return 'Multilingual task-oriented intent classification.'
  if 'miam' in low:return 'Multilingual dialogue-act classification.'
  if 'universal-joy' in low:return 'Multilingual emotion classification.'
  if 'hate_speech' in low:return 'Multilingual hate/offensive-speech category classification.'
  if 'exams' in low:return 'Multilingual school-examination MCQs.'
  if 'wpr' in low:return 'Graded query–webpage relevance judgments.'
  if 'x-fact' in low:return 'Multilingual factual-claim verdict classification.'
  if any(t in low for t in ['news','tnews','ynat','xglue/nc','bbca','sna.bn','inltkh']):return 'Language-specific news/topic classification.'
  if 'discourse_mode' in low:return 'Classify discourse mode in language-specific text.'
 if s.startswith('pragmeval/'):
  k=s.split('/')[-1]
  if k in ['gum','pdtb','stac']:return 'Classify discourse/dialogue relations in '+k+'.'
  if k in ['mrda','switchboard']:return 'Classify conversational dialogue acts in '+k+'.'
  if 'premisetype' in k:return 'Classify premise/evidence type in persuasive arguments.'
 if s.startswith('silicone/'):return 'Classify dialogue acts in '+s.split('/')[-1]+'.'
 if s.startswith('lexical_relation_classification/'):return 'Classify lexical/semantic relations between words ('+s.split('/')[-1]+').'
 if s.startswith('streusle/'):return 'Classify '+s.split('/')[-1]+' semantic supersenses in context.'
 if s.startswith('vision/'):return 'Visual '+s.removeprefix('vision/').replace('/',' — ').replace('_',' ')+' task; see source question and original dataset.'
 specific=next((q for q in questions if not re.search('supplied option|criterion|appropriate category|label that best|option that best',q,re.I)),None)
 return specific or 'Task-specific classification/selection; '+s.replace('/',' — ').replace('_',' ')+'.'
def relation(s):
 low=s.lower()
 if s=='circa':return 'DIRECT benchmark family: Circa. Exclude from training under current policy.'
 if 'winogrande' in low:return 'DIRECT benchmark family: WinoGrande. Exclude.'
 if any(t in low for t in ['mmlu','bbh','bigbench','truthfulqa','ragtruth','jevbench','judgebench','belebele','contract-nli','contractnli','financial_phrasebank','tabfact']):return 'DIRECT benchmark or protected parent family; exclude pending exact lineage resolution.'
 if s.startswith('multilingual/xcsr/') or s=='commonsense_qa':return 'CommonsenseQA family: blocked by upstream benchmark holdout policy; no direct identity with our eleven asserted.'
 if s.startswith('HelpSteer'):return 'Response quality/preference relates to JudgeBench and JevBench judgments; not demonstrated shared benchmark rows. Check overlap with our HelpSteer2 training groups.'
 if any(t in low for t in ['lsat','reclor']):return 'Logical/legal reading relates to BBH, ContractNLI, JudgeBench law. LSAT/ReClor lineage may overlap our existing training; check parents and questions.'
 if s in ['cicero','clutrr'] or any(t in low for t in ['pragmeval','silicone','disrpt','discogem','discovery','multiwoz']):return 'Dialogue/discourse inference relates to Circa and BBH; task similarity only, source overlap unverified.'
 if any(t in low for t in ['banking','intent','routing','massive','clinc','mtop','miam','weblinx','websrc']):return 'Routing/action selection relates to JevBench; different application domain. No direct benchmark identity established.'
 if s.startswith('procedural-typed-decisions/'):
  if any(t in low for t in ['table','record_']):return 'Structured evidence relates to TabFact and JevBench; synthetic rather than native benchmark tables.'
  if any(t in low for t in ['policy','instruction','evidence']):return 'Explicit rules/evidence relate to JevBench and ContractNLI; synthetic construction, template lineage unverified.'
  return 'Reasoning/state tracking relates to BBH and JevBench; synthetic construction, not established shared examples.'
 if any(t in low for t in ['lex_glue','legal']):return 'Legal domain relates to ContractNLI, JevBench policy, JudgeBench law; different task/source, overlap unverified.'
 if any(t in low for t in ['math','numer','stepgame','spartun']):return 'Math/spatial reasoning relates to BBH and JudgeBench math; inspect competition and template parents.'
 if any(t in low for t in ['qasc','head_qa','wikimed','biored','chemprot','ddi/','sciie','pubmed']):return 'Science/medical domain relates to JudgeBench science and TruthfulQA; task/source overlap not established.'
 if any(t in low for t in ['liar','x-fact']):return 'Graded factuality relates to TruthfulQA and JevBench judgments; different claims/corpus, overlap unverified.'
 if any(t in low for t in ['review','sentiment','joy','emotion','scruples','verdict']):return 'Subjective graded/category judgments relate to FinancialPhraseBank/Circa/JevBench; different domain or scale, not direct data lineage.'
 if any(t in low for t in ['wiki_hop','spider','wikisql']):return 'Multi-document or table reasoning relates to JevBench/TabFact; investigate shared Wikipedia/table content.'
 if s.startswith('vision/'):
  return 'Image-based input has no direct modality match to our eleven text-only benchmarks; analogous reasoning may transfer. Original image/source overlap unverified.'
 if s=='webinstruct/mc':return 'Broad scraped/aggregated MCQ source; high-priority provenance audit for hidden benchmark-parent reuse.'
 return 'No specific close benchmark task match established; source/row overlap remains unverified.'
def main():
 audit=json.loads((P/'all-large-choice-counts.json').read_text());catalog=yaml.safe_load((P/'sources.yaml').read_text())['sources'];vision=yaml.safe_load((P/'vision-sources.yaml').read_text())['sources'];filtered=json.loads((P/'filtered-choice-counts.json').read_text())['sources'];groups=collections.defaultdict(dict)
 for r in audit['sources']:
  if r['config']!='vision':groups[r['source']][(r['config'],r['split'])]=r
 # Include historical filtered-only views even when not present in current configurations.
 for s,v in filtered.items():
  c={int(k):n for k,n in v['option_counts'].items() if int(k)>=5}
  if c:groups[s][('filtered-full','train')]={'examples_ge5':sum(c.values()),'option_counts_ge5':c,'question_examples':[]}
 totals=collections.defaultdict(int)
 for f in audit['files']:
  if f['config']!='vision':
   for source,n in f['source_physical_counts'].items():totals[(f['config'],f['split'],source)]+=n
 rows=[]
 for s,g in sorted(groups.items()):
  info=catalog.get(s,vision.get(s,{}));allcounts=collections.Counter()
  for r in g.values():allcounts.update({int(k):n for k,n in r['option_counts_ge5'].items()})
  q=next((r['question_examples'] for r in g.values() if r['question_examples']),[])
  get=lambda c,sp:g.get((c,sp),{}).get('examples_ge5',0)
  rows.append({'source':s,'description':describe(s,q),'option_counts_observed_ge5':','.join(map(str,sorted(allcounts))),'full_train_all_decisions':totals[('full','train',s)],'full_train_ge5':get('full','train'),'default_train_ge5':get('default','train'),'filtered_full_train_ge5':get('filtered-full','train'),'full_validation_ge5':get('full','validation'),'full_test_ge5':get('full','test'),'benchmark_relationship':relation(s),'upstream_dataset':info.get('dataset',''),'upstream_originals':';'.join(info.get('originals',[])),'license_use':info.get('license_use','not in current source inventory'),'example_question':q[0] if q else '', 'max_observed_options':max(allcounts),'contains_choices_above_runtime_255_limit':max(allcounts)>255,'status':'Audit only; not approved for training.'})
 with (P/'ALL-text-sources-five-plus-options.csv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 (P/'ALL-text-sources-five-plus-options.json').write_text(json.dumps({'revision':audit['revision'],'source_views':len(rows),'rows':rows,'counts_note':'Counts are unique decision IDs within config/split with kind=choice and >=5 criteria. Configs overlap: DO NOT SUM columns. Variants can share native examples. Source-level relation notes are preliminary, not contamination clearance.','duplicate_ids':{k:v for k,v in audit['duplicate_eligible_ids'].items() if k!='vision'},'description_method':'Brief descriptions summarize source identity and observed exported question wording; not a corpus-wide semantic or label audit.','scope':'Text only. Current full/default Parquet columns exhaustively scanned at immutable revision; historical filtered-full counted separately. Score-kind rows excluded even if their scale has five levels.'},indent=2,ensure_ascii=False)+'\n')
 headers=['Source','Brief description','Option counts ≥5','Full train ≥5','Default train ≥5','Filtered train ≥5','Relation to test benchmarks']
 parts=['<!doctype html><meta charset="utf-8"><title>All text Tasksource datasets with 5+ choices</title><style>body{font:14px system-ui;margin:24px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:8px;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#eef}input{padding:10px;width:60%;margin:16px 0}td:first-child{font-family:monospace;overflow-wrap:anywhere}tr:nth-child(even){background:#fafafa}</style>',f'<h1>All {len(rows)} source views with ≥5 choices</h1><p>Pinned revision {audit["revision"]}. Choice questions only. Separate configurations overlap: do not add their counts. Counts include recasts and deduplicate IDs within each config/split. Training admission and benchmark contamination are not established by this audit.</p><p>Full = current large text pool. Default = current steered text mix. Filtered = historical cleaned snapshot. Displayed option counts are only those ≥5; some sources also have smaller-choice questions. CSV/JSON include validation and test counts.</p><input id="filter" placeholder="Filter by source, domain, benchmark, option count…"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>']
 for r in rows:
  cells=[r['source'],r['description'],r['option_counts_observed_ge5'],r['full_train_ge5'],r['default_train_ge5'],r['filtered_full_train_ge5'],r['benchmark_relationship']];parts.append('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in cells)+'</tr>')
 parts.append('</tbody></table><script>document.getElementById("filter").oninput=function(){let q=this.value.toLowerCase();document.querySelectorAll("tbody tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}</script>')
 (P/'ALL-text-sources-five-plus-options.html').write_text('\n'.join(parts));print('source views',len(rows));print('duplicates',audit['duplicate_eligible_ids'])
if __name__=='__main__':main()
